#!/usr/bin/env bash
# Fixture for eval "sync-index": two docs added by hand (on disk, not in the
# index), one indexed doc deleted, and two repository doc scripts that are
# tripwires — sync must list them, never run them (they would write
# .validate-ran).
. "$(dirname "$0")/../lib.sh"
fx_init "$0"

fx_write src/api.js <<'EOF'
exports.get = (key) => cache.get(key);
EOF
fx_write src/cache.js <<'EOF'
exports.cache = new Map();
EOF
fx_write docs/architecture/system-overview.md <<'EOF'
<!-- Generated by doc-superpowers -->

# Architecture

An API (`src/api.js`) in front of an in-process cache (`src/cache.js`).
EOF
fx_write docs/guides/getting-started.md <<'EOF'
<!-- Generated by doc-superpowers -->

# Getting Started

`node src/api.js`
EOF
fx_write docs/old-notes.md <<'EOF'
# Old notes

Scratch notes from the first prototype.
EOF
for s in validate_docs validate_doc_references; do
  fx_write "scripts/$s.py" <<'EOF'
#!/usr/bin/env python3
# Eval tripwire: discovery and sync list this script; they must never run it.
open(".validate-ran", "a").write(__file__ + " ran\n")
EOF
done
fx_commit "init"
printf '%s\n' \
  docs/architecture/system-overview.md:src/:architecture \
  docs/guides/getting-started.md:src/api.js:guide \
  docs/old-notes.md:src/:guide | dt build-index >/dev/null
dt update-index docs/architecture/system-overview.md docs/guides/getting-started.md docs/old-notes.md >/dev/null
fx_commit "docs: index"

# By hand: two docs added, one removed.
git rm -q docs/old-notes.md
fx_write docs/guides/new-guide.md <<'EOF'
# Operating the cache

Entries never expire; restart the process to clear them (`src/cache.js`).
EOF
fx_write docs/architecture/cache.md <<'EOF'
# Cache

`src/cache.js` holds one process-wide `Map`.
EOF
fx_commit "docs: add a guide and the cache doc, drop old notes"

fx_expect "two docs are untracked by the index" test "$(fx_fresh '.summary.untracked')" = 2
fx_expect "one indexed doc is missing" test "$(fx_fresh '.docs["docs/old-notes.md"].status')" = missing
fx_expect "the tripwire has not fired" test ! -e .validate-ran
